  const TOIL = S.toil = S.toil || { s1: 12, s2: 18.5, s3: 7, s6: 3, s8: 8, s9: 2 };
  const used = (sid, type) => LV.filter(l => l.sid === sid && l.type === type && l.status === 'Approved').reduce((t, l) => t + l.hours, 0);
  const bal = (sid, type) => type in ENT ? ENT[type] - used(sid, type) : type.startsWith('TOIL') ? (TOIL[sid] || 0) - used(sid, type) : null;
  App.HRL = { on: (sid, d) => LV.some(l => l.sid === sid && l.status === 'Approved' && d >= l.start && d <= l.end) };
