  const roleClash = l => { const p = staff(l.sid); return LV.filter(o => o.id !== l.id && o.status === 'Approved' && staff(o.sid).role === p.role && o.start <= l.end && o.end >= l.start).map(o => staff(o.sid).name); };
  const LF = App.ui.leave = App.ui.leave || { tab: 'req', date: 'All', type: 'All Types', status: 'All Statuses', staff: 'All', role: 'All Roles', q: '' };
