  App.route('/finance/validation/:sid', sid => { const p = staff(sid); if (!p) return ''; const js = wkAdj(sid, W.wk).sort((a, b) => a.date.localeCompare(b.date)), r = payRow(sid, W.wk), o = ot(sid, W.wk), pend = js.some(j => j.status === 'Pending'), extra = js.filter(j => j.status === 'Approved').reduce((t, j) => t + j.hours, 0), late = js.filter(j => j.status === 'Approved' && j.type === 'Adjust in Late Arrival').reduce((t, j) => t + j.hours, 0);
    return `<div class="row between g12 wrap"><div class="row g12"><a class="btn outlined sm rt-pill-btn" href="#/finance/validation"><i class="ri-arrow-left-s-line"></i>Back</a><div><div class="row g8 wrap"><h1 class="pt-h1" style="margin:0">${esc(p.name)}</h1><span class="bz-pill">${r.kind}</span><span class="rt-date"><i class="ri-calendar-line"></i>${wkLabel(W.wk)}</span></div><span class="caption">${esc(App.biz ? App.biz().name : 'LeafEase')} · ${esc(p.role)}</span></div></div>${st(pend ? 'In Review' : r.status)}</div>
      <div class="wf-kpis">${[['Contracted Hours', r.contracted + ' h', ''], ['Worked Hours', +(r.contracted + o - r.unpaid - r.late).toFixed(2) + ' h', 'grey'], ['Overtime hours', '+' + o + ' h', 'green'], ['Days with overtime', String(js.filter(j => j.type === 'Overtime' || j.type === 'TOIL').length).padStart(2, '0'), 'orange'], ['Late Arrivals Covered', late + ' h', 'red']].map(([t, v, c]) => `<div class="wf-kpi ${c}"><span>${t}</span><b>${v}</b></div>`).join('')}</div>
      <section class="card stack"><div class="row between wf-dbh"><h2 class="lv-h2" style="margin:0">Daily Breakdown</h2>${pend ? approveBtn('wf-dall', sid, 'Approve All') : ''}</div><div class="table-scroll"><table class="dt lv-dt"><thead><tr><th>Date</th><th>Extra Hrs.</th><th>Requested as</th><th><i class="ri-sparkling-2-line"></i> AI Analysis</th><th>Actions</th></tr></thead><tbody>
      ${js.map(j => `<tr><td>${dmy(j.date)}</td><td class="good">${j.hours}h</td><td>${esc(j.type)}</td><td class="wf-ai"><i class="ri-sparkling-2-line"></i>${esc(ai(j))}${j.reason ? `<small class="caption">Staff note: “${esc(j.reason)}”</small>` : ''}</td><td>${j.status === 'Pending' ? `<div class="row g6 nowrap">${approveBtn('wf-dok', j.id)}<button class="btn outlined sm at-cancel" data-act="wf-dno" data-id="${j.id}"><i class="ri-close-circle-line"></i>Reject</button></div>` : st(j.status)}</td></tr>`).join('') || '<tr class="empty-row"><td colspan="5">No extra hours requested this week.</td></tr>'}</tbody></table></div><p class="wf-total"><b>Total Extra Hours Approved:</b> ${extra} hrs</p></section>
      ${App.field('Manager Notes (Optional)', `<textarea rows="3" data-in="wf-note" data-id="${sid}" placeholder="Add notes about this payroll review (visible to Finance team)…">${esc(r.note)}</textarea>`, { cls: 'multi' })}
      <div class="row g12"><button class="btn outlined lg rt-pill-btn" data-act="wf-adjust2" data-id="${sid}">Adjust Hours</button><button class="btn primary lg rt-pill-btn" data-act="wf-dsub" data-id="${sid}" ${pend ? 'disabled title="Decide every day first"' : ''}>Submit</button>${pend ? '<span class="caption">Approve or reject every day to submit.</span>' : ''}</div>`; },
    () => ({ key: 'wfv', icon: 'ri-shield-check-line', title: 'Workforce Validation' }));
  acts['wf-dok'] = el => asMenu(el, a => { const j = ADJ.find(x => x.id === el.dataset.id); Object.assign(j, { status: 'Approved', type: a }); keep(); });
  acts['wf-dno'] = el => { ADJ.find(x => x.id === el.dataset.id).status = 'Rejected'; keep(); };
  acts['wf-dall'] = el => asMenu(el, a => { decide([el.dataset.id], 'Approved', a); keep(); });
  ins['wf-note'] = el => { payRow(el.dataset.id, W.wk).note = el.value; };
  acts['wf-adjust2'] = el => adjDlg(el.dataset.id, true);
  acts['wf-dsub'] = el => { payRow(el.dataset.id, W.wk).status = 'Approved'; App.go('#/finance/validation'); W.tab = 'sum'; App.snack(`${staff(el.dataset.id).name}’s week reviewed and approved for payroll.`); };
  // submit approved week → vertical Overtime Reports
  const REP = S.otReports = S.otReports || [];
  const mkRep = (biz, wk, by, at, rows) => ({ id: 'rep' + biz.replace(/\W/g, '') + wk, biz, wk, by, at, rows });
  if (!REP.length) { const seedRows = n => RS.slice(0, n).map((s, i) => ({ sid: s.id, name: s.name, kind: 'Salaried', days: [[0, 4.5, 0, 'Emergency coverage'], [1, 4, 0, ''], [2, 2.5, 0, 'Extended clinic hours'], [4, 0, 9, 'Day off']].slice(0, 3 + (i % 2)) }));
    REP.push(mkRep('LeafEase', '2026-10-19', 'Sofia Sadiq', '2026-10-24', seedRows(3)), mkRep('LeafEase', '2026-10-12', 'Sofia Sadiq', '2026-10-17', seedRows(2)), mkRep('Weightfall', '2026-10-12', 'Noah Jackson', '2026-10-17', seedRows(3)), mkRep('LeafEase', '2026-10-05', 'Sofia Sadiq', '2026-10-10', seedRows(3))); }
  App.OTR = REP;
  acts['wf-submit'] = () => { const rows = RS.map(s => payRow(s.id, W.wk)), open = rows.filter(r => r.status === 'In Review').length, ok = rows.filter(r => r.status === 'Approved');
    App.dialog(PT.modal('ri-send-plane-line', 'Submit week to Finance?', `Week of ${wkLabel(W.wk)} · ${esc(App.biz ? App.biz().name : 'LeafEase')}`, `${open ? `<div class="pt-warn"><i class="ri-alert-line"></i><span>${open} staff ${open === 1 ? 'is' : 'are'} still in review and won’t be included.</span></div>` : ''}<p class="body2" style="margin:0">${ok.length} approved staff will be sent to the Finance team as an overtime report, with your notes and adjustments.</p>`, `<button class="btn outlined lg" data-act="close-modal">Cancel</button><button class="btn primary lg" data-act="wf-submit-go" ${ok.length ? '' : 'disabled'}>Submit to Finance</button>`, 'green'), { width: 500 }); };
  acts['wf-submit-go'] = () => { const biz = App.biz ? App.biz().name : 'LeafEase', rows = RS.map(s => payRow(s.id, W.wk)).filter(r => r.status === 'Approved').map(r => ({ sid: r.sid, name: staff(r.sid).name, kind: r.kind, note: r.note, adj: r.adj, days: wkAdj(r.sid, W.wk).filter(j => j.status === 'Approved').map(j => [(D(j.date) - D(W.wk)) / 864e5, j.type === 'Unpaid Leave' ? 0 : j.hours, j.type === 'Unpaid Leave' ? j.hours : 0, j.type + (j.reason ? ' · ' + j.reason : '')]) }));
    const i = REP.findIndex(x => x.biz === biz && x.wk === W.wk), rep = mkRep(biz, W.wk, App.me().name, TODAY, rows); if (i >= 0) REP[i] = rep; else REP.unshift(rep); App.closeModal(); keep(); App.snack(`Week sent to Finance: ${rows.length} staff in “${repName(rep)}”.`); };
  const repName = r => `Report Week ${String(Math.ceil(+r.wk.slice(8) / 7) + 1).padStart(2, '0')} (${r.wk.slice(8)}–${add(r.wk, 4).slice(8)})`;

