  const OR = App.ui.otr = App.ui.otr || { biz: 'All', wk: 'All', q: '', sel: new Set() };
  const repHours = r => r.rows.reduce((t, x) => t + x.days.reduce((u, d) => u + d[1], 0), 0);
  App.route('/private/overtime', () => { const L = REP.filter(r => (OR.biz === 'All' || r.biz === OR.biz) && (OR.wk === 'All' || r.wk === OR.wk) && (!OR.q || (repName(r) + r.biz + r.by).toLowerCase().includes(OR.q.toLowerCase())));
    const k = [['ri-bar-chart-box-line', 'Total Approved Reports', REP.length, 'on'], ['ri-time-line', 'Total Overtime Hours', repHours({ rows: REP.flatMap(r => r.rows) }) + ' h'], ['ri-calendar-check-line', 'Reports This Month', REP.filter(r => r.at.slice(0, 7) === TODAY.slice(0, 7)).length], ['ri-calendar-line', 'Days with overtime', new Set(REP.flatMap(r => r.rows.flatMap(x => x.days.filter(d => d[1]).map(d => add(r.wk, d[0]))))).size]];
    return App.VH.frame('overtime', `<div class="aq-mh"><span class="aq-hic"><i class="ri-file-chart-line"></i></span><div class="grow"><h1>Overtime Reports</h1><span>Payroll reports approved by each business and ready for download</span></div><button class="btn primary" data-act="or-csv"><i class="ri-file-excel-2-line"></i>Export CSV</button></div>
      <div class="or-kpis">${k.map(([i, t, v, on]) => `<div class="or-kpi ${on || ''}"><span class="at-ki"><i class="${i}"></i></span><div><span>${t}</span><b>${v}</b></div></div>`).join('')}</div>
      <div class="bm-card"><div class="bm-filters">${App.field('Business', `<select data-ch="or-f" data-k="biz"><option value="All">All businesses</option>${[...new Set(REP.map(r => r.biz))].map(b => `<option ${OR.biz === b ? 'selected' : ''}>${esc(b)}</option>`).join('')}</select>`, { cls: 'select' })}${App.field('Week', `<select data-ch="or-f" data-k="wk"><option value="All">All weeks</option>${[...new Set(REP.map(r => r.wk))].sort().reverse().map(w => `<option value="${w}" ${OR.wk === w ? 'selected' : ''}>${wkLabel(w)}</option>`).join('')}</select>`, { cls: 'select' })}${App.field('Search', `<i class="ri-search-line"></i><input type="search" data-in="or-q" value="${esc(OR.q)}" placeholder="Search here…" aria-label="Search reports">`)}</div>
      <div class="table-card"><div class="table-scroll"><table class="dt lv-dt"><thead><tr><th>Report Name</th><th>Business</th><th>Week</th><th>Report Date</th><th>Staff Members</th><th>Overtime</th><th>Approved By</th><th>Actions</th></tr></thead><tbody>
      ${L.map(r => `<tr class="click" data-go="#/private/overtime/${r.id}"><td><b class="fw5">${repName(r)}</b></td><td>${esc(r.biz)}</td><td>${wkLabel(r.wk)}</td><td>${dmy(r.at)}</td><td>${r.rows.length} Staff</td><td class="good">${repHours(r)}h</td><td>${esc(r.by)}</td><td><span class="row-actions"><a class="icon-btn s20" href="#/private/overtime/${r.id}" aria-label="View report"><i class="ri-eye-line"></i></a><button class="icon-btn s20" data-act="or-dl" data-id="${r.id}" aria-label="Download report"><i class="ri-download-2-line"></i></button></span></td></tr>`).join('') || '<tr class="empty-row"><td colspan="8">No reports match these filters.</td></tr>'}</tbody></table></div></div></div>`, [['Overtime Reports']]); },
    { key: 'portal', portal: true, icon: 'ri-file-chart-line', title: 'Overtime Reports' });
  chs['or-f'] = el => { OR[el.dataset.k] = el.value; keep(); };
